import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, it, expect } from "vitest";
import type {
  DissolveEffect,
  FlipbookEffect,
  ParticleEmitter,
  ParticleEmitterProcess,
  ParticleMaterial,
  ParticlesEffect,
  SpineEffect,
  SpineSlotEmitter,
  SpriteShaderEffect,
  SpriteShaderTweener,
  TransformAnimEffect,
  VfxEffect,
  VfxManifest,
} from "../manifest";

// The EXTRACTED manifest, read for real. `VfxManifest` is hand-written
// TypeScript and this file is generated by `sts2-wiki/scripts/extract_vfx.py`
// — two sides of one contract with nothing between them. Checking the shipped
// artifact against the type is the only thing that catches them drifting, as
// they already had once (`clip` was typed `string` while the extractor writes
// `str | None`).
//
// Read at RUNTIME, not `import`ed. A static import makes the file a compile
// dependency of `tsc -b`, and the extracted art tree is `.dockerignore`d
// (`sts2-wiki/site`, line 23) while the image's web stage copies only
// `sts2-pycli/web/` — so a static import fails `npm run build` inside the
// container, which is exactly how this broke the first deploy after the
// feature landed. Absent tree => the suite skips; present tree => it checks.
// (This comment used to add "gitignored" as a second reason. It is not:
// `sts2-wiki/.gitignore` says of the extracted images "These are committed
// since they're needed for the site build", and `git ls-files` on that tree
// lists 3258 of them. `.dockerignore` alone is the real reason.)
// `__dirname`, not `import.meta.url`: vitest transforms this module so its
// `import.meta.url` is not a `file:` URL (`fileURLToPath` throws). This is
// the same resolution `sfxMapCoverage.test.ts` uses.
const WEB_ROOT = resolve(__dirname, "../../..");
const MANIFEST_PATH = resolve(
  WEB_ROOT,
  "../../sts2-wiki/site/public/images/vfx/manifest.json",
);

function readManifest(): VfxManifest | null {
  try {
    // The double cast type-checks NOTHING, deliberately: parsed JSON is `any`,
    // and even a static import WIDENS every literal (`"spine"` -> `string`)
    // and tuple (`[0, 25]` -> `number[]`), so an annotation would fail on the
    // widening rather than on any drift. All the work is done by the key
    // tables below: they are `Record<keyof T, …>`, so a field added to the
    // TYPE fails to compile here, a field added by the EXTRACTOR fails the
    // exact-keys assertion, and every field's value is checked against the
    // interface.
    return JSON.parse(readFileSync(MANIFEST_PATH, "utf8")) as VfxManifest;
  } catch {
    return null;
  }
}

const loaded = readManifest();

/** Assert `obj` has exactly `spec`'s keys, each passing its predicate. Reused
 *  at every nesting level (effect / emitter / emitter.process) rather than
 *  duplicated per level, so a field added to any of them — by the TYPE or by
 *  the EXTRACTOR — is caught the same way `FLIPBOOK_KEYS`/`SPINE_KEYS`
 *  already caught the top-level `clip` drift this file's header describes. */
function checkExactShape(
  obj: Record<string, unknown>,
  spec: Record<string, (v: unknown) => boolean>,
  label: string,
  /** Keys the TYPE declares optional (`?:`), which the extractor omits rather
   *  than writing empty — `SpineEffect.emitters` is the only one (GH #669).
   *  Absent is a pass; PRESENT still has to satisfy its predicate, so the
   *  exemption buys the key its absence and nothing else. */
  optional: readonly string[] = [],
): void {
  for (const [field, ok] of Object.entries(spec)) {
    expect(ok(obj[field]), `${label}.${field} = ${JSON.stringify(obj[field])}`).toBe(true);
  }
  // ...and nothing the type does NOT declare, so a field the extractor
  // starts writing is noticed here rather than ignored at runtime.
  const expected = Object.keys(spec).filter(
    (k) => !(optional.includes(k) && obj[k] === undefined),
  );
  expect(Object.keys(obj).sort(), label).toEqual(expected.sort());
}

/** {@link SpineEffect} keys the extractor omits when there is nothing to say. */
const SPINE_OPTIONAL_KEYS = ["emitters"] as const;

/** Every key of the effect interfaces, so a field ADDED to the type
 *  without being added here fails to compile. */
const FLIPBOOK_KEYS: Record<keyof FlipbookEffect, (v: unknown) => boolean> = {
  kind: (v) => v === "flipbook",
  frames: (v) => Array.isArray(v) && v.length > 0 && v.every((f) => typeof f === "string"),
  fps: (v) => typeof v === "number",
  loop: (v) => typeof v === "boolean",
  scale: (v) => typeof v === "number",
  randomizeRotation: (v) => typeof v === "boolean",
  rotationRange: (v) => Array.isArray(v) && v.length === 2 && v.every((n) => typeof n === "number"),
};

const SPINE_KEYS: Record<keyof SpineEffect, (v: unknown) => boolean> = {
  kind: (v) => v === "spine",
  rig: (v) => typeof v === "string",
  scale: (v) => typeof v === "number",
  // Nullable on purpose: `SpineVfxSpec.clip` is `str | None`.
  clip: (v) => v === null || typeof v === "string",
  // ABSENT for a spine scene with no slot-parented emitters, which is every
  // one but `vfx_kaiser_crab_boss_explosion` (GH #669) — so `undefined` is a
  // pass, and an empty array is not: the extractor omits the key rather than
  // writing `[]`.
  emitters: (v) => {
    if (v === undefined) return true;
    if (!Array.isArray(v) || v.length === 0) return false;
    v.forEach((em, i) =>
      checkExactShape(em as Record<string, unknown>, SPINE_SLOT_EMITTER_KEYS, `emitters[${i}]`),
    );
    return true;
  },
};

const isNum = (v: unknown): boolean => typeof v === "number";
const isBool = (v: unknown): boolean => typeof v === "boolean";
const isNullableString = (v: unknown): boolean => v === null || typeof v === "string";
const isNumTuple = (n: number) => (v: unknown): boolean =>
  Array.isArray(v) && v.length === n && v.every((x) => typeof x === "number");

/** `ParticleEmitterProcess`'s 53 fields (Godot `ParticleProcessMaterial`,
 *  extracted verbatim). Every `*Curve`/`colorRamp` field is a
 *  `vfx_particles/<hash>.json` LUT path or `null` — `colorInitialRamp` is
 *  the one exception (an inline baked 256-stop RGBA gradient, not a path). */
const PARTICLE_PROCESS_KEYS: Record<keyof ParticleEmitterProcess, (v: unknown) => boolean> = {
  alphaCurve: isNullableString,
  colorInitialRamp: (v) =>
    v === null || (Array.isArray(v) && v.every((stop) => isNumTuple(4)(stop))),
  colorRamp: isNullableString,
  dampingCurve: isNullableString,
  dampingMax: isNum,
  dampingMin: isNum,
  direction: isNumTuple(3),
  flatness: isNum,
  gravity: isNumTuple(3),
  initialVelocityMax: isNum,
  initialVelocityMin: isNum,
  lifetimeRandomness: isNum,
  animOffsetMin: isNum,
  animOffsetMax: isNum,
  animSpeedMin: isNum,
  animSpeedMax: isNum,
  animSpeedCurve: isNullableString,
  angleMin: isNum,
  angleMax: isNum,
  angleCurve: isNullableString,
  angularVelocityMin: isNum,
  angularVelocityMax: isNum,
  angularVelocityCurve: isNullableString,
  emissionShape: isNum,
  emissionSphereRadius: isNum,
  emissionBoxExtents: isNumTuple(3),
  emissionRingAxis: isNumTuple(3),
  emissionRingHeight: isNum,
  emissionRingRadius: isNum,
  emissionRingInnerRadius: isNum,
  emissionRingConeAngle: isNum,
  emissionShapeOffset: isNumTuple(3),
  emissionShapeScale: isNumTuple(3),
  particleFlagAlignY: isBool,
  particleFlagDampingAsFriction: isBool,
  particleFlagDisableZ: isBool,
  particleFlagRotateY: isBool,
  radialVelocityCurve: isNullableString,
  radialVelocityMax: isNum,
  radialVelocityMin: isNum,
  scaleCurve: isNullableString,
  scaleMax: isNum,
  scaleMin: isNum,
  scaleOverVelocityCurve: isNullableString,
  scaleOverVelocityMax: isNum,
  spread: isNum,
  turbulenceEnabled: isBool,
  turbulenceInfluenceMax: isNum,
  turbulenceInfluenceMin: isNum,
  turbulenceInfluenceOverLifeCurve: isNullableString,
  turbulenceInitialDisplacementMax: isNum,
  turbulenceInitialDisplacementMin: isNum,
  turbulenceNoiseScale: isNum,
  turbulenceNoiseSpeed: isNumTuple(3),
  turbulenceNoiseSpeedRandom: isNum,
  turbulenceNoiseStrength: isNum,
};

/** `ParticleMaterial` — the `.tres` ShaderMaterial's uniforms. `lut` is what
 *  colourises the grayscale texture, so a shape regression here is a
 *  wrong-coloured effect rather than a crash. */
const PARTICLE_MATERIAL_KEYS: Record<keyof ParticleMaterial, (v: unknown) => boolean> = {
  path: (v) => typeof v === "string",
  shader: (v) => typeof v === "string",
  lut: isNullableString,
  frameCount: (v) => v === null || typeof v === "number",
  flipbookSize: (v) => v === null || isNumTuple(2)(v),
  flipbookCurve: isNullableString,
  useErosion: isBool,
  useHueShift: isBool,
};

const isParticleMaterial = (v: unknown): boolean =>
  typeof v === "object" &&
  v !== null &&
  Object.entries(PARTICLE_MATERIAL_KEYS).every(([k, check]) =>
    check((v as Record<string, unknown>)[k]),
  );

const PARTICLE_EMITTER_KEYS: Record<keyof ParticleEmitter, (v: unknown) => boolean> = {
  name: (v) => typeof v === "string",
  texture: (v) => typeof v === "string",
  material: (v) => v === null || isParticleMaterial(v),
  amount: isNum,
  cpu: isBool,
  explosiveness: isNum,
  fixedFps: isNum,
  lifetime: isNum,
  localCoords: isBool,
  offset: isNumTuple(2),
  oneShot: isBool,
  randomness: isNum,
  rotation: isNum,
  selfModulate: isNumTuple(4),
  startDelay: isNum,
  underPivotScale: isBool,
  underMirrorX: isBool,
  zIndex: isNum,
  // GH #669. `null` / `false` on every composite emitter; a Spine effect's
  // own slot emitters are the only ones that carry either.
  slot: isNullableString,
  blendAdd: isBool,
  // GH #669. `false` / `0.3` on every composite emitter; the crab explosion's
  // ember burst is the one emitter in scope that enables trails.
  trailEnabled: isBool,
  trailLifetime: isNum,
  process: (v) => {
    if (typeof v !== "object" || v === null) return false;
    checkExactShape(v as Record<string, unknown>, PARTICLE_PROCESS_KEYS, "process");
    return true;
  },
};

/** A Spine effect's own slot emitter: every `ParticleEmitter` key, plus a
 *  non-null `slot` and the rig event that restarts it (GH #669). */
const SPINE_SLOT_EMITTER_KEYS: Record<keyof SpineSlotEmitter, (v: unknown) => boolean> = {
  ...PARTICLE_EMITTER_KEYS,
  slot: (v) => typeof v === "string" && v.length > 0,
  event: (v) => typeof v === "string" && v.length > 0,
};

const PARTICLES_KEYS: Record<keyof ParticlesEffect, (v: unknown) => boolean> = {
  kind: (v) => v === "particles",
  lifetime: isNum,
  emitters: (v) => {
    if (!Array.isArray(v) || v.length === 0) return false;
    v.forEach((em, i) => checkExactShape(em as Record<string, unknown>, PARTICLE_EMITTER_KEYS, `emitters[${i}]`));
    return true;
  },
  // Scene node names from the extracted `.tscn`, not asset paths — no
  // path-shape check applies to either of these.
  mirrorX: isNullableString,
  pivotScale: (v) =>
    v === null ||
    (Array.isArray(v) && v.length === 3 && typeof v[0] === "string" && isNum(v[1]) && isNum(v[2])),
  tinted: isBool,
};

const TRANSFORM_ANIM_KEYS: Record<keyof TransformAnimEffect, (v: unknown) => boolean> = {
  kind: (v) => v === "transform_anim",
  lifetime: isNum,
  sprites: (v) => {
    if (!Array.isArray(v) || v.length === 0) return false;
    // `checkExactShape`, not inline predicates: this file's contract is that
    // a field the EXTRACTOR starts writing is caught too, and an inline
    // `&&` chain only checks the fields it happens to name.
    v.forEach((s, i) =>
      checkExactShape(s as Record<string, unknown>, TRANSFORM_ANIM_SPRITE_KEYS, `sprites[${i}]`),
    );
    return true;
  },
};

const TRANSFORM_ANIM_SPRITE_KEYS: Record<
  keyof TransformAnimEffect["sprites"][number],
  (v: unknown) => boolean
> = {
  name: (v) => typeof v === "string",
  texture: (v) => typeof v === "string",
  // Nullable, not optional: a null channel is one the animation never
  // touches, and the extractor always writes the key.
  positionX: isNullableString,
  positionY: isNullableString,
  rotation: isNullableString,
  // The scene node's own authored transform, which a null channel above
  // holds. Always a number — Godot's node default (0) where the scene omits
  // it — never null, or the renderer would be back to guessing zero.
  restPositionX: isNum,
  restPositionY: isNum,
  restRotation: isNum,
};

const DISSOLVE_KEYS: Record<keyof DissolveEffect, (v: unknown) => boolean> = {
  kind: (v) => v === "dissolve",
  shader: (v) => typeof v === "string",
  blendMode: (v) => typeof v === "string",
  gradient1: (v) => typeof v === "string",
  gradient2: (v) => typeof v === "string",
  modulateAlpha: isNum,
  thresholdFrom: isNum,
  thresholdTo: isNum,
  dissolveEase: isNum,
  dissolveTrans: isNum,
  dissolveSeconds: isNum,
  lifetime: isNum,
  emitters: (v) => {
    if (!Array.isArray(v) || v.length === 0) return false;
    v.forEach((em, i) => checkExactShape(em as Record<string, unknown>, PARTICLE_EMITTER_KEYS, `emitters[${i}]`));
    return true;
  },
  // A FRACTION of the creature's extent, never the scene's placeholder 99.23
  // (`NMonsterDeathVfx.cs:231` overwrites it at runtime).
  emissionRadiusPerCreatureExtent: (v) => isNum(v) && (v as number) < 1,
};

const TWEENER_KEYS: Record<keyof SpriteShaderTweener, (v: unknown) => boolean> = {
  property: (v) => v === "scale" || v === "modulateAlpha",
  to: isNum,
  duration: isNum,
  // `null` = the game overrides neither ease nor transition for this tweener.
  ease: (v) => v === null || isNum(v),
  trans: (v) => v === null || isNum(v),
};

const SPRITE_SHADER_KEYS: Record<keyof SpriteShaderEffect, (v: unknown) => boolean> = {
  kind: (v) => v === "sprite_shader",
  shader: (v) => typeof v === "string",
  blendMode: (v) => typeof v === "string",
  strength: isNum,
  scale: isNum,
  modulateAlpha: isNum,
  tween: (v) => {
    if (!Array.isArray(v) || v.length === 0) return false;
    v.forEach((step, i) => {
      expect(Array.isArray(step) && step.length > 0, `tween[${i}]`).toBe(true);
      (step as unknown[]).forEach((t, j) =>
        checkExactShape(t as Record<string, unknown>, TWEENER_KEYS, `tween[${i}][${j}]`),
      );
    });
    return true;
  },
  lifetime: isNum,
};

/** Effect `kind` -> its key table. A map rather than a ternary chain so a kind
 *  with no entry cannot silently be checked against whichever table the chain
 *  happened to end on — which is how `transform_anim` came to be validated
 *  against `PARTICLES_KEYS`.
 *
 *  Keyed by `VfxEffect["kind"]` rather than `string`: a kind added to the
 *  union without a table here fails to COMPILE, which is a gate on the commit
 *  that adds it. A `Record<string, …>` would only fail at RUNTIME, and only
 *  once an effect of that kind reached the committed manifest — the same
 *  one-release-late detection that let this bug ship in the first place. */
const KEYS_BY_KIND: { [K in VfxEffect["kind"]]: Record<string, (v: unknown) => boolean> } = {
  flipbook: FLIPBOOK_KEYS,
  spine: SPINE_KEYS,
  particles: PARTICLES_KEYS,
  transform_anim: TRANSFORM_ANIM_KEYS,
  dissolve: DISSOLVE_KEYS,
  sprite_shader: SPRITE_SHADER_KEYS,
};

// Skipped, loudly, wherever the extracted art tree is absent (a fresh clone
// that has not run `just extract-vfx`, and the container build). Vitest
// reports the suite as skipped rather than passing it vacuously.
const suite = loaded ? describe : describe.skip;
// Narrowed for the body: the suite only runs when `loaded` is non-null, and
// `describe.skip` never invokes this callback.
const manifest = loaded as VfxManifest;

suite("the committed vfx manifest", () => {
  it("carries a revision", () => {
    // The art bucket serves frames `immutable` at non-content-addressed URLs;
    // `?v=<rev>` is the only cache bust there is.
    expect(typeof manifest.rev).toBe("string");
    expect(manifest.rev).toBeTruthy();
  });

  it("has every field VfxManifest declares, at the declared type", () => {
    const effects = Object.entries(manifest.effects);
    expect(effects.length).toBeGreaterThan(0);
    for (const [name, e] of effects) {
      const spec = KEYS_BY_KIND[e.kind];
      expect(spec, `${name}: no key table for kind ${e.kind}`).toBeDefined();
      checkExactShape(
        e as unknown as Record<string, unknown>,
        spec,
        name,
        e.kind === "spine" ? SPINE_OPTIONAL_KEYS : [],
      );
    }
  });

  it("has at least one particle composite, so PARTICLES_KEYS is actually exercised", () => {
    // Design spec: 13 particle composites. A committed manifest that
    // regressed to zero would make the branch above vacuously true.
    const kinds = Object.values(manifest.effects).map((e) => e.kind);
    expect(kinds.filter((k) => k === "particles").length).toBeGreaterThan(0);
  });

  it("names paths the asset resolver can serve", () => {
    // `assetUrl(rel)` resolves against the images root, which IS `images_root`
    // in the extractor.
    for (const [name, e] of Object.entries(manifest.effects)) {
      if (e.kind === "flipbook") {
        for (const f of e.frames) expect(f.startsWith("vfx/"), `${name}: ${f}`).toBe(true);
      } else if (e.kind === "spine") {
        expect(e.rig.startsWith("vfx_rigs/"), name).toBe(true);
      } else if (e.kind === "transform_anim") {
        for (const s of e.sprites) {
          // The RESOLVER ROOT, not just a `.png` suffix — this test exists to
          // check that a path resolves against the images root, and every
          // extension check in the file would pass on a path served from
          // nowhere. `ui/`, not `vfx/`: `vfx_block_broken`'s halves are the
          // combat HUD's own block-break sprites, a third root beside `vfx/`
          // and `animations/`.
          expect(s.texture.startsWith("ui/"), `${name}.${s.name}.texture: ${s.texture}`).toBe(true);
          for (const [chan, lut] of [
            ["positionX", s.positionX],
            ["positionY", s.positionY],
            ["rotation", s.rotation],
          ] as const) {
            // A null channel is one the animation never touches — skip it
            // rather than demanding a path that is deliberately absent.
            if (lut !== null) {
              expect(lut.startsWith("vfx_particles/"), `${name}.${s.name}.${chan}: ${lut}`).toBe(
                true,
              );
            }
          }
        }
      } else if (e.kind === "sprite_shader") {
        // No asset paths at all: the texture is assigned at runtime from the
        // power's `BigIcon`, so there is nothing here for the resolver to serve.
        expect(typeof e.shader, name).toBe("string");
      } else {
        if (e.kind === "dissolve") {
          for (const g of [e.gradient1, e.gradient2]) {
            expect(g.startsWith("vfx/"), `${name}: ${g}`).toBe(true);
          }
        }
        for (const em of e.emitters) {
          // The extractor names textures under both `vfx/` and `animations/`
          // (e.g. `vfx_sandy_impact`'s emitters) — unlike flipbook frames,
          // which are always `vfx/`.
          expect(
            em.texture.startsWith("vfx/") || em.texture.startsWith("animations/"),
            `${name}.${em.name}.texture: ${em.texture}`,
          ).toBe(true);
          if (em.material !== null) {
            expect(
              em.material.path.startsWith("materials/"),
              `${name}.${em.name}.material.path: ${em.material.path}`,
            ).toBe(true);
          }
          // Typed as a literal tuple (`as const`), not `(keyof
          // ParticleEmitterProcess)[]` — the latter widens `field` to ALL 34
          // keys inside the loop, so indexing `em.process[field]` would type
          // as the union of every field's value (numbers, tuples, ...), not
          // just this subset's `string | null`.
          const curveFields = [
            "alphaCurve",
            "colorRamp",
            "dampingCurve",
            "radialVelocityCurve",
            "scaleCurve",
            "scaleOverVelocityCurve",
            "turbulenceInfluenceOverLifeCurve",
          ] as const;
          for (const field of curveFields) {
            const v = em.process[field];
            if (v !== null) {
              expect(v.startsWith("vfx_particles/"), `${name}.${em.name}.process.${field}: ${v}`).toBe(true);
            }
          }
        }
      }
    }
  });
});
